// Gap flagging (FR-23): record which optional inputs are missing so the report
// can surface this explicitly rather than silently proceeding.
// v0.2: audit_notification moved from optional to mandatory.
const required = ['completed_audit_working_file', 'kickoff_deck', 'audit_notification'];
const optional = ['process_understanding', 'analysis_sheet'];
const items = $input.all();
const engagementId = items[0]?.json.engagement_id;
const present = new Set(items.map(i => i.json.doc_type).filter(Boolean));
const missingRequired = required.filter(t => !present.has(t));
if (missingRequired.length) {
  throw new Error('Missing mandatory input(s): ' + missingRequired.join(', '));
}
const gaps = optional.filter(t => !present.has(t));
return [{ json: { engagement_id: engagementId, input_gaps: gaps } }];
